def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the full separator row or column.
    sep_col = next(
        (c for c in range(w)
         if all(grid[r][c] == grid[0][c] for r in range(h))),
        None
    )
    sep_row = next(
        (r for r in range(h)
         if all(v == grid[r][0] for v in grid[r])),
        None
    )

    if sep_col is not None:
        left = [row[:sep_col] for row in grid]
        right = [row[sep_col + 1:] for row in grid]
        width = min(len(left[0]), len(right[0]))
        common = set(v for row in left for v in row) & set(
            v for row in right for v in row
        )
        mismatch = min(common)
        out = []
        for r in range(h):
            out.append([
                3 if left[r][c] == right[r][c] else mismatch
                for c in range(width)
            ])
        return out

    top = grid[:sep_row]
    bottom = grid[sep_row + 1:]
    height = min(len(top), len(bottom))
    common = set(v for row in top for v in row) & set(
        v for row in bottom for v in row
    )
    mismatch = min(common)
    return [
        [
            3 if top[r][c] == bottom[r][c] else mismatch
            for c in range(w)
        ]
        for r in range(height)
    ]
